/// <summary>
/// Business event triggered when a production order is scheduled.
/// </summary>
[BusinessEvents(classStr(AAXProdOrderScheduledBusinessEventContract), 'ProdOrderScheduledBusinessEventName', 'ProdOrderScheduledBusinessEventDescription', ModuleAxapta::Production)]
public final class AAXProdOrderScheduledBusinessEvent extends BusinessEventsBase
{
    private ProdTable prodTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source ProdTable for building the event contract.
/// </summary>
private ProdTable parmProdTable(ProdTable _prodTable = prodTable)
{
    prodTable = _prodTable;

    return prodTable;
}

/// <summary>
/// Creates a new <c>AAXProdOrderScheduledBusinessEvent</c> instance from the specified <c>ProdTable</c> record.
/// </summary>
/// <param name="_prodTable">The source ProdTable record.</param>
/// <returns>A new instance of <c>AAXProdOrderScheduledBusinessEvent</c>.</returns>
public static AAXProdOrderScheduledBusinessEvent newFromProdTable(ProdTable _prodTable)
{
    AAXProdOrderScheduledBusinessEvent businessEvent = new AAXProdOrderScheduledBusinessEvent();
    businessEvent.parmProdTable(_prodTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXProdOrderScheduledBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXProdOrderScheduledBusinessEventContract::newFromProdTable(prodTable);
}
